begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local timezone='Pacific/Honolulu';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','agenda-'||n||'@example.invalid','x',now(),now(),now() from generate_series(1,6) n;
insert into public.staff_users(user_id,role) values('a9000000-0000-4000-8000-000000000001','admin'),('a9000000-0000-4000-8000-000000000002','office'),('a9000000-0000-4000-8000-000000000003','technician'),('a9000000-0000-4000-8000-000000000004','technician');
insert into public.customers(id,name) values('c9000000-0000-4000-8000-000000000001','Klient Alfa'),('c9000000-0000-4000-8000-000000000002','Klient Beta');
insert into public.staff_customer_assignments(user_id,customer_id) values('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000001'),('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000002'),('a9000000-0000-4000-8000-000000000004','c9000000-0000-4000-8000-000000000001');
insert into public.customer_memberships(user_id,customer_id) values('a9000000-0000-4000-8000-000000000005','c9000000-0000-4000-8000-000000000001');
create function pg_temp.task(n integer,who integer default 3,delta integer default 0,state text default 'todo',client integer default 1) returns jsonb language sql as $$select public.save_crm_record(('c9000000-0000-4000-8000-'||lpad(client::text,12,'0'))::uuid,'tasks',('d9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,null,jsonb_build_object('title',case when who=4 then 'HIDDEN OTHER TASK' else 'Działanie '||n end,'description','TASK DESCRIPTION','kind','follow_up','dueOn',to_char((now() at time zone 'Europe/Warsaw')::date+delta,'YYYY-MM-DD'),'assigneeId','a9000000-0000-4000-8000-'||lpad(who::text,12,'0'),'contactId',null,'state',state,'result',''))$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select pg_temp.task(1),pg_temp.task(2,3,0,'done'),pg_temp.task(3,3,0,'cancelled'),pg_temp.task(4,2,0,'todo',2);
select is(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'task'->>'version','0','Fresh context contains current version');
select is((select count(*)::int from jsonb_array_elements(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'assignees') item where item->>'id' like 'a9000000-%'),4,'Available office and assigned technicians only');
select is((select count(*)::int from jsonb_array_elements(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000002','d9000000-0000-4000-8000-000000000004')->'assignees') item where item->>'id' like 'a9000000-%'),3,'Options depend on customer scope');
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000002','d9000000-0000-4000-8000-000000000001')$$,'42501',null,'Foreign task context denied');
select is(public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',0,'a9000000-0000-4000-8000-000000000004',to_char((now() at time zone 'Europe/Warsaw')::date+2,'YYYY-MM-DD'))->>'version','1','Atomic reassignment and deadline change');
select is(public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',0,'a9000000-0000-4000-8000-000000000004',to_char((now() at time zone 'Europe/Warsaw')::date+2,'YYYY-MM-DD'))->>'version','1','Identical retry does not increment version');
select is(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'task'->>'description','TASK DESCRIPTION','Description preserved');
select is(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'task'->>'kind','follow_up','Task kind preserved');
select is(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'task'->>'state','todo','Status preserved');
reset role;
select is((select count(*)::int from public.audit_logs where table_name='crm_tasks' and row_id='d9000000-0000-4000-8000-000000000001'),2,'Exactly one change audit besides creation after retry');
set local role authenticated;
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',0,'a9000000-0000-4000-8000-000000000003','2030-01-01')$$,'40001',null,'Stale plan rejected');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000002','d9000000-0000-4000-8000-000000000001',1,'a9000000-0000-4000-8000-000000000002','2030-01-01')$$,'42501',null,'Cannot move a task to a different customer');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000002','d9000000-0000-4000-8000-000000000004',0,'a9000000-0000-4000-8000-000000000004','2030-01-01')$$,'22023',null,'Cannot assign unscoped technician');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'a9000000-0000-4000-8000-000000000005','2030-01-01')$$,'22023',null,'Portal client is not a valid assignee');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'a9000000-0000-4000-8000-000000000004','2026-02-30')$$,'22023',null,'Impossible date rejected');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'a9000000-0000-4000-8000-000000000004','2101-01-01')$$,'22023',null,'Out of range date rejected');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',null,'a9000000-0000-4000-8000-000000000004','2030-01-01')$$,'22023',null,'Version required');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000002',0,'a9000000-0000-4000-8000-000000000004','2030-01-01')$$,'40001',null,'Completed task cannot be replanned');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000003',0,'a9000000-0000-4000-8000-000000000004','2030-01-01')$$,'40001',null,'Cancelled task cannot be replanned');
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000002')$$,'40001',null,'Completed context does not offer editor');
select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'in_progress','Work in progress');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'a9000000-0000-4000-8000-000000000003','2030-01-01')$$,'40001',null,'Concurrent progress is not overwritten');
select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',2,'a9000000-0000-4000-8000-000000000003','2030-01-01');
select is(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'task'->>'result','Work in progress','Result preserved by partial plan update');
select is(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'task'->>'state','in_progress','In progress state preserved');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000004',true);
select is(public.my_crm_tasks('open')->>'total','0','Former assignee loses task from personal agenda');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is(public.my_crm_tasks('open')->>'total','1','New assignee receives personal task');
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')$$,'42501',null,'Technician cannot read planning directory');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',3,'a9000000-0000-4000-8000-000000000003','2030-01-02')$$,'42501',null,'Technician cannot replan own task');
reset role;
delete from public.staff_customer_assignments where user_id='a9000000-0000-4000-8000-000000000004';
insert into public.account_access(user_id,blocked) values('a9000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from jsonb_array_elements(public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')->'assignees') item where item->>'id' like 'a9000000-%'),2,'Options exclude blocked and revoked technicians');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',3,'a9000000-0000-4000-8000-000000000004','2030-01-02')$$,'22023',null,'Revoked scope checked again at write');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',3,'a9000000-0000-4000-8000-000000000003','2030-01-02')$$,'22023',null,'Blocked assignee rejected at write');
select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',3,'a9000000-0000-4000-8000-000000000002','2030-01-02');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')$$,'42501',null,'Portal client denied context');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',4,'a9000000-0000-4000-8000-000000000002','2030-01-03')$$,'42501',null,'Portal client denied changes');
reset role;
update public.customers set archived_at=now() where id='c9000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')$$,'40001',null,'Archived customer context blocked');
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',4,'a9000000-0000-4000-8000-000000000002','2030-01-03')$$,'40001',null,'Archived customer write blocked');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000006',true);
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')$$,'42501',null,'No-role account denied');
reset role;
insert into public.account_access(user_id,blocked) values('a9000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.change_crm_task_plan('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',4,'a9000000-0000-4000-8000-000000000001','2030-01-03')$$,'42501',null,'Blocked office denied');
reset role;
set local role anon;
select throws_ok($$select public.crm_task_plan_context('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001')$$,'42501',null,'Anonymous context execution denied');
select * from finish();
rollback;
